class LCSyllabus(BaseModel):
    subject: typing.Optional[types.LC6Subject] = Field(default=None, description='The per-subject discriminator; selects the active payload')
    language: typing.Optional[types.LC6Language] = Field(default=None, description='The source language of the syllabus PDF')
    source_pdf: typing.Optional[str] = Field(default=None, description='Path or filename of the source NCCA syllabus PDF')
    source_pages: typing.Optional[int] = Field(default=None, description='PDF page count, when known')
    level: typing.Optional[str] = Field(default=None, description='NCCA stage: \'LC_FL\' / \'LC_OL\' / \'LC_HL\' / \'JC\' (Foundation / Ordinary / Higher / Junior Cycle)')
    topic_count: typing.Optional[int] = Field(default=None, description='Total number of topics / modules extracted from the syllabus')
    learning_outcome_count: typing.Optional[int] = Field(default=None, description='Total number of learning outcomes across all topics')
    document: typing.Optional["LCSyllabusDocument"] = None
    extracted_at: typing.Optional[str] = Field(default=None, description='ISO datetime the extraction ran')
    extracted_by: typing.Optional[str] = Field(default=None, description='Always \'lc6_unified_extractor\' for this file')

class LCSyllabusDiagram(BaseModel):
    diagram_id: typing.Optional[str] = None
    kind: typing.Optional[str] = Field(default=None, description='EXTRACTED_FROM_DOCUMENT | ANNOTATED | DIAGRAM_BASED | ...')
    caption_en: typing.Optional[str] = None
    caption_ga: typing.Optional[str] = None
    page_number: typing.Optional[int] = None
    source_pdf: typing.Optional[str] = None
    subject: typing.Optional[types.LCSubjectSlug] = None
    pointing_model: typing.Optional[str] = Field(default=None, description='e.g., \'allenai/Molmo2-8B\'')
    confidence_score: typing.Optional[float] = None
    regions: typing.List["LCDiagramRegion"]
    related_lo_ids: typing.List[str] = Field(description='NCCA LO codes the diagram illustrates')
    lineage: typing.Optional["LineageTrace"] = None

class LCSyllabusDocument(BaseModel):
    subject: typing.Optional[types.LCSubjectSlug] = None
    language: typing.Optional[str] = Field(default=None, description='EN | GA | EN_AND_GA')
    stage: typing.Optional[types.LCEducationStage] = None
    source_pdf: typing.Optional[str] = None
    source_pages: typing.Optional[int] = Field(default=None, description='Nullable per the 2026-08-06 token-plan-apis convention')
    module_topics: typing.List["LCModule"]
    total_learning_outcomes: typing.Optional[int] = None
    cross_curricular: typing.List[str]
    assessment_objectives: typing.List[str]
    prescribed_texts: typing.Optional[typing.List["LCBilingualText"]] = Field(default=None, description='For English + Gaeilge')
    formulas: typing.Optional[typing.List[str]] = Field(default=None, description='Formula references (for Mathematics, Physics, Accounting)')
    lineage: typing.Optional["LineageTrace"] = None

