class LeabharlannDoc(BaseModel):
    file_name: typing.Optional[str] = Field(default=None, description='The basename of the file (e.g. \'CT511_assignment_2024.pdf\')')
    source_subdir: typing.Optional[types.LeabharlannSubcorpus] = Field(default=None, description='Which of the 6 sub-corpora (gaeilge | aigne | mata | ollscoil_na_gaillimhe | zotero | gemini_deep_research)')
    file_type: typing.Optional[str] = Field(default=None, description='Lowercased extension: pdf | docx | epub | md | pages | py | ipynb | bib')
    doc_kind: typing.Optional[types.LeabharlannDocKind] = Field(default=None, description='The kind of document (book chapter, paper, coursework, exam, ...)')
    doc_language: typing.Optional[types.LeabharlannLanguage] = Field(default=None, description='Primary language of the document')
    doc_title: typing.Optional[str] = Field(default=None, description='Cleaned title of the document, with newline artefacts removed')
    doc_summary: typing.Optional[str] = Field(default=None, description='2-3 sentence summary of the document content')
    author_names: typing.List[str] = Field(description='Ordered list of author names (best-effort from the text); empty for anonymous')
    publication_year: typing.Optional[int] = Field(default=None, description='4-digit publication year, or null if not discernible')
    course_code: typing.Optional[str] = Field(default=None, description='Course code (e.g. CT511, GA101, ED305, MA335) if discernible; null for non-coursework')
    programme_code: typing.Optional[str] = Field(default=None, description='Programme code (e.g. HDSD, BScMS) if discernible; null for non-coursework')
    key_topics: typing.List[str] = Field(description='3-7 single-sentence topics, ordered by importance')
    irish_relevant: typing.Optional[bool] = Field(default=None, description='True if the document is about the Irish language, in Irish, or related to Celtic studies')
    math_relevant: typing.Optional[bool] = Field(default=None, description='True if the document contains mathematical content (LaTeX, equations, statistics)')
    arxiv_id: typing.Optional[str] = Field(default=None, description='Bare arXiv identifier (e.g. \'2504.02890\') if the document is an arXiv preprint; null otherwise')
    arxiv_version: typing.Optional[str] = Field(default=None, description='arXiv version (e.g. \'v2\') if discernible; null otherwise')
    doi: typing.Optional[str] = Field(default=None, description='Digital Object Identifier (formatted \'10.xxxx/xxxx\' without the \'doi:\' prefix); null if not visible')
    paper_venue: typing.Optional[str] = Field(default=None, description='Journal or conference name for journal/conference papers; null otherwise')
    paper_abstract: typing.Optional[str] = Field(default=None, description='Abstract if visible in the first 2 pages; null otherwise')
    gemini_research_date: typing.Optional[str] = Field(default=None, description='ISO 8601 (YYYY-MM-DD) Gemini deep-research date, or null')
    cited_urls: typing.List[str] = Field(description='Cited URLs in the Gemini deep-research PDF (deduplicated); empty for non-Gemini')
    programme_stage: typing.Optional[str] = Field(default=None, description='Programme stage: undergraduate, PGCE, masters, PhD, professional, or unknown (UoG artefacts only)')
    needs_ocr: typing.Optional[bool] = Field(default=None, description='True if the document contains handwriting that needs OCR / HTR (.pages files, scanned PDFs)')
    approximate_word_count: typing.Optional[int] = Field(default=None, description='Approximate word count if discernible (within +/- 20%); null otherwise')
    cited_paper_arxiv_ids: typing.List[str] = Field(description='arXiv IDs of papers cited by this document; empty if none detected')
    references_uog_codes: typing.List[str] = Field(description='UoG course codes referenced by this document; empty if none detected')
    confidence: typing.Optional[float] = Field(default=None, description='Overall LLM self-rated confidence 0.0-1.0')

